const hexVal =
	"";

const hexToNumber = () => {
	const dec = BigInt(`0x${hexVal}`);

	console.log(dec);
};

const hexToString = () => {
	let str = "";
	for (let i = 0; i < hexVal.length; i += 2) {
		const byte = hexVal.substring(i, i + 2);
		str += String.fromCharCode(parseInt(byte, 16));
	}
	console.log(str);
};

const hexToAddress = () => {
	const address = "0x" + hexVal.slice(-40);
	console.log(address);
};

hexToNumber();
hexToString();
hexToAddress();
